    @DisplayName("Can decode")
    public void randomKeyCipherCanDecode() {
        String cipherText = "aaaaaaaaaa";
        assertThat(randomKeyCipher.decode(randomKeyCipher.getKey().substring(0, 10)))
            .isEqualTo(cipherText);
    }

